-- ---------- Code pénal du cabinet : texte des articles (transcription de la feuille Google) ----------
-- Relancer ce fichier remplace toute la table.
drop table if exists cabinet_code_penal_texte;
create table cabinet_code_penal_texte (
  id text primary key,
  numero text not null,
  partie text,
  titre_rubrique text,
  chapitre text,
  texte text not null default '',
  applicable text,
  ordre integer not null default 0,
  created_at timestamptz not null default now()
);
alter table cabinet_code_penal_texte enable row level security;

insert into cabinet_code_penal_texte (id, numero, partie, titre_rubrique, chapitre, texte, applicable, ordre) values
  ('APréambule', 'Préambule', 'Partie I', 'Titre I – Principes généraux du droit pénal', null, 'Le présent Code pénal est adopté par l''Etat fédéré de San Andreas conformément à la Constitution des Etats-Unis, aux Amendements constitutionnels applicables, ainsi qu''à la Constitution de l''Etat de San Andreas.

Les dispositions du présent Code sont interprétées conformément au Statut d''interprétation et d''application des lois de l''Etat de San Andreas.

Définitions générales :
Est considérée comme une arme tout objet conçu ou utilisé pour porter atteinte à l''intégrité physique d''autrui.
Constitue une autorité publique toute personne investie d''une mission de service public ou exerçant une fonction publique, administrative ou de sécurité.
Est considéré comme lieu public tout lieu accessible au public, de manière libre ou conditionnelle.
Un ordre est légal lorsqu''il est donné par une autorité compétente dans le cadre de ses fonctions et conformément à la loi.', null, 1),
  ('A1101', '1101', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 1 - Hiérarchie des normes', 'Toute disposition du présent Code s''interprète et s''applique conformément à la Constitution des Etats-Unis, à ses amendements, ainsi qu''à la Constitution de l''Etat de San Andreas. Toute disposition contraire est réputée inapplicable.', null, 2),
  ('A1102', '1102', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 1 - Hiérarchie des normes', 'Nul ne peut être poursuivi, condamné ou sanctionné pénalement sans le respect strict des garanties procédurales, du droit à un procès équitable et du principe du contradictoire.', null, 3),
  ('A1201', '1201', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 2 - Légalité et responsabilité pénale', 'Nul ne peut être déclaré coupable d''une infraction pénale si les faits reprochés ne sont pas expressément définis par la loi en vigueur au moment de leur commission.', null, 4),
  ('A1202', '1202', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 2 - Légalité et responsabilité pénale', 'La loi pénale ne peut s''appliquer rétroactivement, sauf lorsqu''elle est plus favorable à la personne poursuivie.', null, 5),
  ('A1203', '1203', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 2 - Légalité et responsabilité pénale', 'Nul n''est pénalement responsable que de son propre fait.', null, 6),
  ('A1301', '1301', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 3 - Élément intentionnel', 'Sauf disposition expresse contraire, les infractions définies par le présent Code requièrent la preuve d''un comportement intentionnel, en connaissance de cause, imprudent ou négligent, conformément aux catégories définies ci-dessous.', null, 7),
  ('A1302', '1302', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 3 - Élément intentionnel', 'Une infraction est intentionnelle lorsque l''auteur a agi avec la volonté délibérée de commettre l''acte prohibé ou d''provoquer le résultat.', null, 8),
  ('A1303', '1303', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 3 - Élément intentionnel', 'Une infraction est commise en connaissance de cause lorsque l''auteur savait que son comportement était susceptible de produire un résultat prohibé.', null, 9),
  ('A1304', '1304', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 3 - Élément intentionnel', 'Une infraction est commise par imprudence lorsque l''auteur a consciemment pris un risque substantiel et injustifié.', null, 10),
  ('A1305', '1305', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 3 - Élément intentionnel', 'Une infraction est commise par négligence lorsque l''auteur n''a pas perçu un risque que toute personne raisonnable aurait identifié dans les mêmes circonstances.', null, 11),
  ('A1401', '1401', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 4 - Tentative, complicité et concours', 'Il y a tentative lorsqu''une personne, avec l''intention requise, accomplit un acte substantiel en vue de la commission d''une infraction, sans que celle-ci n''aboutisse.', null, 12),
  ('A1402', '1402', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 4 - Tentative, complicité et concours', 'Est pénalement responsable comme auteur ou complice toute personne qui aide, encourage, ordonne ou facilite la commission d''une infraction.', null, 13),
  ('A1403', '1403', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 4 - Tentative, complicité et concours', 'La conspiration est constituée lorsqu''au moins deux personnes s''entendent en vue de commettre une infraction et accomplissent un acte manifeste en ce sens.', null, 14),
  ('A1501', '1501', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 5 - Causes d''exonération', 'N''est pas pénalement responsable la personne qui fait un usage raisonnable et proportionné de la force lorsqu''elle croit raisonnablement faire face à une menace immédiate et illégale (Titre II du présent Code).', null, 15),
  ('A1502', '1502', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 5 - Causes d''exonération', 'L''usage de la force létale peut être justifié dans un lieu où la personne est légalement présente, lorsque celle-ci a une croyance raisonnable et objective qu''une telle force est nécessaire pour prévenir un décès, une blessure grave ou un crime violent.', null, 16),
  ('A1601', '1601', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 6 - Prescription de l''action pénale', 'L''action pénale s''éteint par l''écoulement d''un délai de prescription à compter de la commission de l''infraction, sous réserve des exceptions prévues par la loi.', null, 17),
  ('A1602', '1602', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 6 - Prescription de l''action pénale', 'Sauf disposition contraire, le délai de prescription est de :
- quatorze (14) jours pour les infractions mineures,
- vingt-et-un (21) jours pour les délits,
- soixante (60) jours pour les crimes.
Les crimes majeurs sont imprescriptibles.', null, 18),
  ('A1603', '1603', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 6 - Prescription de l''action pénale', 'Le délai de prescription court à compter du jour où l''infraction a été commise. Pour les infractions dissimulées ou continues, le délai court à compter du jour où elles ont été révélées ou ont cessé.', null, 19),
  ('A1604', '1604', 'Partie I', 'Titre I – Principes généraux du droit pénal', 'Chapitre 6 - Prescription de l''action pénale', 'Tout acte d''enquête, de poursuite ou de jugement régulièrement accompli interrompt le délai de prescription.', null, 20),
  ('A2101', '2101', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 1 - Principes généraux', 'L''usage de la force, y compris de la force létale, engage la responsabilité pénale de son auteur, sauf lorsqu''il est justifié par une cause d''irresponsabilité prévue par le présent Titre.', null, 21),
  ('A2102', '2102', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 1 - Principes généraux', 'La légalité de l''usage de la force est appréciée souverainement par l''autorité judiciaire, au regard des circonstances connues ou raisonnablement perçues par l''auteur au moment des faits.', null, 22),
  ('A2201', '2201', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 2 - Légitime défense', 'N''est pas pénalement responsable la personne qui fait usage de la force de manière nécessaire et proportionnée afin de se défendre ou de défendre autrui contre une agression illégale, imminente et réelle.', null, 23),
  ('A2202', '2202', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 2 - Légitime défense', 'La légitime défense est reconnue lorsque les conditions suivantes sont réunies :
- l''existence d''une agression illégale,
- le caractère imminent de cette agression,
- la nécessité de la riposte,
- la proportionnalité entre la gravité de l''agression et moyens de défense employés.', null, 24),
  ('A2203', '2203', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 2 - Légitime défense', 'Lorsque la légitime défense est invoquée de manière crédible, il appartient à l''accusation d''établir l''absence d''une ou plusieurs conditions prévues à l''Article 2202.', null, 25),
  ('A2301', '2301', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 3 - Usage de la force létale', 'L''usage de la force létale n''est justifié qu''en cas de menace immédiate et raisonnablement perçue de mort, de blessure grave ou de crime violent majeur.', null, 26),
  ('A2302', '2302', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 3 - Usage de la force létale', 'L''usage de la force létale ne peut être justifié par la seule protection de biens matériels, en l''absence de menace directe contre les personnes.', null, 27),
  ('A2401', '2401', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 4 - Devoir de retrait', 'Hors des exceptions prévues par le présent Titre, une personne doit, lorsque cela est raisonnablement possible et sans danger accru, se retirer ou éviter la confrontation avant de faire usage de la force létale.', null, 28),
  ('A2402', '2402', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 4 - Devoir de retrait', 'Une personne légalement présente en un lieu où elle est autorisée à se trouver n''a pas l''obligation de se retirer avant de faire usage de la force, y compris létale, lorsque les conditions de la légitime défense prévues aux Articles 2201 et 2202 sont réunies.', null, 29),
  ('A2501', '2501', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 5 - Doctrine Castle', 'Lorsqu''une personne fait usage de la force contre un intrus ayant pénétré illégalement et de manière violente dans un domicile, un véhicule occupé ou un lieu privé assimilé, l''existence d''une menace grave est présumée, sauf preuve contraire.', null, 30),
  ('A2502', '2502', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 5 - Doctrine Castle', 'La présomption prévue à l''Article 2501 ne s''applique pas lorsque :
- l''intrus est un agent public agissant légalement,
- l''auteur a provoqué intentionnellement l''intrusion,
- l''intrus ne représente manifestement pas une menace.', null, 31),
  ('A2601', '2601', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 6 - Exclusions et abus', 'La légitime défense ne peut être invoquée par une personne ayant volontairement provoqué l''agression, sauf si elle a manifestement tenté de se désengager.', null, 32),
  ('A2602', '2602', 'Partie I', 'Titre II – Usage de la force et légitime défense', 'Chapitre 6 - Exclusions et abus', 'L''usage de la force excédant manifestement ce qui était nécessaire ou proportionné exclut le bénéfice des dispositions du présent Titre.', null, 33),
  ('A3101', '3101', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 1 - Catégories d''infractions', 'Les infractions pénales sont classées comme suit :
- infractions mineures,
- délits,
- crimes.', null, 34),
  ('A3201', '3201', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 2 - Principes de sanction', 'Toute peine doit être proportionnée à la gravité de l''infraction, au degré de culpabilité et aux circonstances de sa commission.', null, 35),
  ('A3202', '3202', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 2 - Principes de sanction', 'Aucune amende ou peine ne peut être excessive au sens du Huitième Amendement de la Constitution des Etats-Unis d''Amérique et de la Section 13 de l''Article Ier de la Constitution de l''Etat de San Andreas.', null, 36),
  ('A3203', '3203', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 2 - Principes de sanction', 'La peine capitale constitue une sanction pénale exceptionnelle applicable sur l''ensemble du territoire de l''Etat de San Andreas.
Elle ne peut être prononcée que par la Cour Suprême de l''Etat de San Andreas.
Les conditions de jugement et d''exécution sont fixées par le Code de procédures pénales.', null, 37),
  ('A3301', '3301', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 3 - Détermination des peines', 'Selon le niveau de l''infraction commise, une peine nominale est appliquée (cf. Livret des peines). Cette peine nominale peut être ajustée selon certains facteurs atténuants ou aggravants.', null, 38),
  ('A3302', '3302', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 3 - Détermination des peines', 'Peuvent notamment constituer des circonstances aggravantes :
- l''usage ou la menace d''une arme,
- la préméditation,
- la pluralité de victimes,
- l''abus d''autorité de fonction,
- la vulnérabilité particulière de la victime,
- la participation à une organisation criminelle,
- Menace et intimidation sur agents des service public.
- Les crimes et délits portant atteinte à l''intégrité physique d''un agent des services publics en service.', null, 39),
  ('A3303', '3303', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 3 - Détermination des peines', 'Peuvent notamment constituer des circonstances atténuantes :
- l''absence d''antécédents,
- la coopération avec les autorités,
- la réparation volontaire du dommage,
- la contrainte ou l''influence significative,
- l''âge ou l''état de santé.', null, 40),
  ('A3304', '3304', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 3 - Détermination des peines', 'L''aggravation d''une peine peut être décidée par le juge en fonction des circonstances particulières de l''affaire et de la personnalité de l''auteur, dans les limites prévues par la loi.', null, 41),
  ('A3305', '3305', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 3 - Détermination des peines', 'En cas de concours d''infractions, les amendes peuvent être cumulatives mais seule la plus longue durée d''emprisonnement est appliquée.', null, 42),
  ('A3401', '3401', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 4 - Peines alternatives', 'La probation peut être ordonnée lorsque la réhabilitation du condamné apparaît possible sans incarcération.', null, 43),
  ('A3402', '3402', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 4 - Peines alternatives', 'Des travaux d''intérêt général peuvent être prononcés en substitution ou en complément d''une peine.', null, 44),
  ('A3403', '3403', 'Partie I', 'Titre III – Classification des infractions et sanctions', 'Chapitre 4 - Peines alternatives', 'Le juge peut ordonner des programmes de traitement, de formation ou de suivi psychologique.', null, 45),
  ('A4101', '4101', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait, pour une personne tenue par une obligation légale spécifique d''agir, de s''abstenir volontairement de porter assistance à une personne en danger immédiat est reconnu comme non-assistance à personne en danger et constitue une infraction pénale, lorsqu''une intervention était possible sans risque disproportionné.', null, 46),
  ('A4102', '4102', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait d''exposer délibérément une personne à un risque immédiat de mort ou de blessure grave par un comportement imprudent ou dangereusement irresponsable est reconnu comme mise en danger de la vie d''autrui et constitue une infraction pénale.', null, 47),
  ('A4103', '4103', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait de porter volontairement atteinte à l''intégrité physique d''autrui est reconnu comme violence et constitue une infraction pénale.', null, 48),
  ('A4104', '4104', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait de porter volontairement atteinte à l''intégrité physique d''autrui à l''aide d''une arme blanche, ou de tout objet assimilé par destination, est reconnu comme violence avec arme blanche et constitue une infraction pénale.', null, 49),
  ('A4105', '4105', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait de porter volontairement atteinte à l''intégrité physique d''autrui par l''usage, la menace immédiate ou le tir d''une arme à feu, est reconnu comme violence avec arme à feu et constitue une infraction pénale.', null, 50),
  ('A4106', '4106', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait de commettre volontairement des violences caractérisées par une cruauté extrême ou des traitements inhumains portant atteinte grave à la dignité humaine est reconnu comme acte de barbarie et constitue une infraction pénale.', null, 51),
  ('A4107', '4107', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait d''infliger intentionnellement à une personne des souffrances physiques ou psychologiques graves afin d''obtenir une information, une punition, une intimidation ou un avantage est reconnu comme torture et constitue une infraction pénale.', null, 52),
  ('A4108', '4108', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait de proférer des menaces ou d''exercer des intimidations, par tout moyen, dans le but de contraindre ou d''influencer le comportement d''autrui est reconnu comme menace et intimidation et constitue une infraction pénale.', null, 53),
  ('A4109', '4109', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 1 - Violences et atteintes physiques', 'Le fait de prélever, vendre, acheter, céder, transporter ou obtenir un organe humain en dehors de tout cadre légal, notamment en échange d''une contrepartie financière ou matérielle, est reconnu comme trafic d''organes et constitue une infraction pénale.', null, 54),
  ('A4201', '4201', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 2 - Infractions sexuelles', 'Le fait d''exposer volontairement ses parties intimes dans un lieu public ou accessible au public, sans justification légitime, est reconnu comme exhibition sexuelle et constitue une infraction pénale.', null, 55),
  ('A4202', '4202', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 2 - Infractions sexuelles', 'Toute atteinte sexuelle commise sans consentement libre et éclairé est reconnue comme agression sexuelle et constitue une infraction pénale.', null, 56),
  ('A4203', '4203', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 2 - Infractions sexuelles', 'Tout acte de pénétration sexuelle, de quelque nature qu''il soit, est reconnu comme viol et constitue une infraction pénale.', null, 57),
  ('A4204', '4204', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 2 - Infractions sexuelles', 'Le fait de favoriser, d''organiser, de protéger et/ou de tirer profit de la prostitution d''autrui caractérise le proxénétisme et constitue une infraction pénale, considéré comme un crime majeur.', 'Applicable uniquement à Los Santos.', 58),
  ('A4204.1', '4204.1', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 2 - Infractions sexuelles', 'Le proxénétisme est condamné de 150,000$ d''amende et 120 minutes d''emprisonnement, avec obligation d''être jugé devant un tribunal.', 'Applicable uniquement à Los Santos.', 59),
  ('A4301', '4301', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 3 - Atteintes à la liberté individuelle', 'Le fait de priver une personne de sa liberté de mouvement par violence, menace ou contrainte, en dehors de toute autorité légale, est reconnu comme enlèvement et séquestration et constitue une infraction pénale.', null, 60),
  ('A4302', '4302', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 3 - Atteintes à la liberté individuelle', 'Le fait de détenir, retenir ou séquestrer une personne contre sa volonté, sans exiger de bien matériel et financier en contrepartie de sa libération, constitue une prise d''otage sans rançon. La qualification est subordonnée à l''existence d''un échange de principe intervenant dans le cadre de négociations, pouvant porter sur des engagements opérationnels d''un service public. L''infraction est constituée dès lors que la privation de liberté est volontaire et exercée par menace, violence ou contrainte et constitue une infraction pénale.', null, 61),
  ('A4303', '4303', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 3 - Atteintes à la liberté individuelle', 'Le fait de détenir, retenir ou séquestrer une personne contre sa volonté en exigeant un bien matériel ou financier en contrepartie de sa libération constitue une prise d''otage avec rançon. L''infraction est constituée dès la formulation d''une demande, expresse ou implicite, de rançon, quelle qu''en soit la nature et constitue une infraction pénale.', null, 62),
  ('A4401', '4401', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Le fait de refuser un droit, un service ou un avantage à une personne en raison d''un critère protégé par la loi est reconnu comme discrimination et constitue une infraction pénale, lorsqu''un tel refus n''est pas légalement justifié.', null, 63),
  ('A4402', '4402', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Le fait d''imposer à une personne, de manière répétée, des comportements, communications ou pressions portant atteinte à sa tranquillité, sa dignité ou sa sécurité est reconnu comme harcèlement (ou cyberharcèlement en cas de harcèlement via un moyen de communication électronique) et constitue une infraction pénale.', null, 64),
  ('A4403', '4403', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Le fait de tirer profit de la vulnérabilité d''une personne pour obtenir un avantage indu est reconnu comme abus de faiblesse et constitue une infraction pénale.', null, 65),
  ('A4404', '4404', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Le fait de proférer une insulte grave, offensant un individu, dans le but de l''affecter moralement est reconnu comme injure et constitue une infraction pénale.', null, 66),
  ('A4405', '4405', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Tout propos, comportement ou acte à caractère raciste ou haineux est reconnu comme un délit.

Sont considérés comme propos à caractère raciste toute forme d''expression, parole ou comportement visant à discriminer, humilier ou inciter à la haine envers une personne ou un groupe en raison de son origine, de son ethnie ou de sa couleur de peau.

Toute infraction au présent article est punie d''une amende de quinze mille (15 000) dollars et d''une peine de détention de quinze (15) minutes.', 'Applicable uniquement sur Los Santos.', 67),
  ('A4406', '4406', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Le fait de tenir, publiquement ou en privé, toute allégation ou imputation d''un fait inexact ou non vérifié portant atteinte à l''honneur ou à la réputation d''une personne est reconnu comme diffamation et constitue une infraction pénale.

La diffusion, par tout moyen, de propos diffamatoires est également constitutive de l''infraction.

La diffamation est punie d''une amende de dix mille (10 000) dollars et d''une peine de détention de dix (10) minutes.', null, 68),
  ('A4407', '4407', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 4 - Atteintes à la dignité et à l''égalité', 'Le fait d''imposer à quelqu''un sans son consentement, de façon répétée, des propos ou comportements à connotation sexuelle.
Est constitutif de harcèlement sexuel tout propos ou comportement à caractère sexuel non désiré et répété ayant pour effet de porter atteinte à la dignité d''une personne ou de créer une situation humiliante.', 'Applicable uniquement sur Los Santos.', 69),
  ('A4501', '4501', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 5 - Atteintes à la vie', 'Le fait de causer intentionnellement la mort d''autrui constitue un homicide.', null, 70),
  ('A4502', '4502', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 5 - Atteintes à la vie', 'Le fait de causer la mort d''autrui par imprudence ou négligence grave constitue un homicide involontaire.', null, 71),
  ('A4503', '4503', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 5 - Atteintes à la vie', 'Le fait de donner volontairement la mort à autrui avec préméditation ou dans des circonstances révélant une intention délibérée de tuer est reconnu comme assassinat et constitue une infraction pénale.', null, 72),
  ('A4504', '4504', 'Partie II', 'Titre IV – Infractions contre les personnes', 'Chapitre 5 - Atteintes à la vie', 'Le fait de tenter de tuer ou de causer un préjudice menaçant la vie d''une autre personne, de manière délibérée et intentionnelle, est reconnu comme tentative d''homicide et constitue une infraction pénale.', null, 73),
  ('A5101', '5101', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'La soustraction frauduleuse d''un bien appartenant à autrui est reconnue comme vol et constitue une infraction pénale.', null, 74),
  ('A5102', '5102', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Le fait de soustraire un bien à autrui par la violence, la menace ou l''usage d''une arme est reconnu comme braquage et constitue une infraction pénale.', null, 75),
  ('A5103', '5103', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Le fait de pénétrer illégalement dans un lieu avec l''intention d''y commettre un vol est reconnu comme cambriolage et constitue une infraction pénale.', null, 76),
  ('A5104', '5104', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Le fait de détenir, dissimuler ou utiliser sciemment un bien provenant d''une infraction pénale est reconnu comme recel et constitue une infraction pénale.', null, 77),
  ('A5105', '5105', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Le fait d''obtenir un bien, un service ou un avantage par menace, contrainte ou pression illégitime est reconnu comme extorsion et constitue une infraction pénale.', null, 78),
  ('A5106', '5106', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Le fait de reproduire, distribuer ou utiliser frauduleusement un bien protégé par un droit de propriété intellectuelle est reconnu comme contrefaçon et constitue une infraction pénale.', null, 79),
  ('A5107', '5107', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Est constitutive d''une violation de propriété privée le fait, pour toute personne, de pénétrer ou de se maintenir sans autorisation préalable du propriétaire ou de son représentant légal dans une propriété privée dûment identifiée comme telle. Toute violation de propriété privée est punie d''une amende de 5 000 $ ainsi que d''une peine de 10 minutes d''incarcération.', null, 80),
  ('A5107.1', '5107.1', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Ne constitue pas une violation de propriété privée :
1.L''intervention d''un agent des forces de l''ordre en service, agissant sur présentation d''un mandat délivré par le Bureau du Procureur ou toute autorité judiciaire compétente ou en cas de flagrance d''un délit ou crime nécessitant une intervention immédiate.
2.Toute intervention d''urgence justifiée par un péril imminent mettant en danger la vie ou l''intégrité physique d''une personne.', null, 81),
  ('A5108', '5108', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'Le fait de détruire, dégrader ou détériorer un bien appartenant à autrui, qu''il s''agisse d''un bien public ou privé, est reconnu comme dégradation de bien et constitue une infraction pénale. Toute tentative est punie dans les mêmes conditions.', null, 82),
  ('A5108.1', '5108.1', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'La dégradation de bien est punie d''une amende dont le montant est fixé en fonction de la gravité des dommages constatés et de leur coût estimé.

Cette amende ne peut être inférieure à cinq mille dollars (5 000 $) ni supérieure à cinquante mille dollars (50 000 $).

L''autorité compétente apprécie le montant de l''amende au regard notamment :
• de l''étendue des dégradations ;
• de la valeur du bien concerné ;
• du coût des réparations ou du remplacement ;
• ainsi que des circonstances dans lesquelles les faits ont été commis.', null, 83),
  ('A5108.2', '5108.2', 'Partie II', 'Titre V – Infractions contre les biens', 'Chapitre unique', 'L''infraction de dégradation de bien constitue une infraction autonome.
Elle ne peut être retenue cumulativement avec une infraction de refus d''obtempérer lorsque les dégradations sont commises directement dans le cadre d''une course-poursuite avec les forces de l''ordre.
En dehors de cette situation, les infractions peuvent être retenues cumulativement lorsque les faits sont distincts ou détachables.', null, 84),
  ('A6101', '6101', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Le fait de porter une arme ou munitions soumise à autorisation sans être titulaire du permis requis est reconnu comme défaut de permis de port d''arme civil (PPA) et constitue une infraction pénale.', null, 85),
  ('A6102', '6102', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Le fait de porter une arme de manière visible dans l''espace public lorsque c''est interdit par la loi est reconnu comme exhibition d''arme et constitue une infraction pénale.', null, 86),
  ('A6103', '6103', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Le fait de détenir une arme prohibée ou non enregistrée conformément à la loi est reconnu comme possession d''arme illégale et constitue une infraction pénale.', null, 87),
  ('A6103.1', '6103.1', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'La détention, le port ou le transport d''une arme blanche prohibée ou soumis à autorisation, sans motif légitime ou sans respect des dispositions légales en vigueur, est considéré comme une possession illégale d''arme blanche, et constitue une infraction pénale.', null, 88),
  ('A6103.2', '6103.2', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'La détention, le port ou le transport d''une arme létale prohibée ou non enregistrée conformément à la réglementation en vigueur constitue une possession illégale d''arme, et constitue une infraction pénale.', null, 89),
  ('A6104', '6104', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'La détention d''un gilet pare-balle dans un contexte criminel ou lorsqu''elle est interdite par la loi est reconnu comme possession illégale de gilet pare-balle et constitue une infraction pénale.', null, 90),
  ('A6105', '6105', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Le fait de fabriquer, acquérir, transférer ou distribuer des armes en violation des lois et règlements applicables, notamment dans un cadre organisé, est reconnu comme trafic d''armes et constitue une infraction pénale.', null, 91),
  ('A6106', '6106', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Les armureries agréées par l''État de San Andreas sont reconnues comme des établissements sensibles au regard de la sécurité publique.
Afin de prévenir l''introduction, la dissimulation ou la circulation d''armes illégales, de munitions prohibées ou de tout objet dangereux, des contrôles de sécurité sont obligatoires à l''entrée et à la sortie de ces établissements.
Ces contrôles peuvent comprendre :
- une inspection visuelle des effets personnels ;
- une palpation de sécurité ;
- la vérification de la conformité des armes transportées.
Les contrôles sont effectués exclusivement par des employés préalablement habilités par l''État de San Andreas. L''habilitation est subordonnée à la réussite d''une formation obligatoire dispensée ou validée par un service de police de l''État. Les employés habilités ne disposent d''aucun pouvoir de contrainte physique, de saisie ou de retenue. Toute mesure coercitive ou fouille approfondie relève exclusivement de la compétence des forces de l''ordre. Le refus de se soumettre au contrôle entraîne l''interdiction immédiate d''accès ou l''exclusion de l''établissement.', null, 92),
  ('A6107', '6107', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Le fait pour un civil titulaire d''un Permis de Port d''Arme Civile (PPA) ou d''un permis de chasse valide de détenir simultanément plus d''une arme à feu légale acquise conformément à la loi constitue une infraction pénale. Toute arme excédentaire pourra être saisie.
Cette infraction est punie d''une amende de 15 000 $, d''une peine de 20 minutes d''emprisonnement et peut entraîner la suspension ou le retrait du PPA ou du permis de chasse.', null, 93),
  ('A6108', '6108', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Constitue un usage d''une arme létale tout emploi effectif de ses capacités létales, par activation, tir, projection ou mise en œuvre quelle qu''elle soit. L''usage est caractérisé indépendamment de l''existence d''une atteinte à une personne, de la survenance d''un dommage, de l''intention de porter atteinte à autrui.', 'Applicable uniquement sur Los Santos.', 94),
  ('A6108.1', '6108.1', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'L''article 6108 ne s''applique pas aux stands de tirs des entreprises agréées par la Mairie de Los Santos County, et dans les conditions légales d''usage de la force prévues par les lois de Los Santos.', 'Applicable uniquement sur Los Santos.', 95),
  ('A6108.2', '6108.2', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Le non-respect de l''article 6108 entraînera une amende pécuniaire de 7,500$ et 10 minutes d''emprisonnement.', 'Applicable uniquement sur Los Santos.', 96),
  ('A6109', '6109', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'L''usage d''une arme à feu est autorisé, sous réserve qu''il ne constitue pas un danger injustifié pour autrui et qu''il respecte les règles élémentaires de sécurité et de discernement.', 'Applicable uniquement à Blaine County.', 97),
  ('A6109.1', '6109.1', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Constitue un usage abusif d''une arme à feu tout tir effectué :
- sans motif légitime ;
- en méconnaissance des règles élémentaires de sécurité et de maniement des armes à feu, telles que enseignées lors du test d''aptitude prévu à l''article 4.3, Titre IV de la réglementation des armes de l''État de San Andreas;
- de manière dangereuse, inconsidérée ou disproportionnée ;
- à l''encontre d''un individu, d''un animal ou de tout élément sans justification valable.', 'Applicable uniquement à Blaine County.', 98),
  ('A6109.2', '6109.2', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Les faits mentionnés à l''article 6109.1 sont punis d''une amende de 7 500 $ et d''une peine de 10 minutes de détention.
Lorsque les faits sont commis à l''encontre d''un agent des services publics, les sanctions sont portées à 10 000 $ d''amende et 15 minutes de détention.', 'Applicable uniquement à Blaine County.', 99),
  ('A6109.3', '6109.3', 'Partie II', 'Titre VI – Armes et sécurité publique', 'Chapitre unique', 'Ne constitue pas un usage abusif d''une arme à feu :
- l''usage d''une arme à feu au sein d''un stand de tir autorisé, notamment Ammu-Nation ;
- l''usage dans le cadre d''une activité de chasse réglementée, avec une arme adaptée ;
- toute utilisation encadrée dans un cadre professionnel ou institutionnel.', 'Applicable uniquement à Blaine County.', 100),
  ('A7101', '7101', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Le fait de ne pas se conformer volontairement à un ordre légal donné par une personne dépositaire de l''autorité publique et identifiable comme telle est reconnu comme refus d''obtempérer et constitue une infraction pénale.', null, 101),
  ('A7101.1', '7101.1', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Constitue une circonstance aggravante du refus d''obtempérer le fait, pour toute personne, de franchir volontairement ou de tenter de se soustraire à un dispositif de douanes légalement établi par les forces de police.
Ce fait est puni d''une amende de 3 750 $ et d''une peine de détention de 15 minutes, sans préjudice des poursuites complémentaires prévues par le présent Code.', null, 102),
  ('A7102', '7102', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Le fait de refuser de décliner son identité lors d''un contrôle légalement justifié est reconnu comme refus d''identification et constitue une infraction pénale.', null, 103),
  ('A7102.1', '7102.1', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'La dissimulation volontaire du visage dans l''espace public n''est pas interdite sur le territoire de l''État de San Andreas.
Toutefois, lors d''un contrôle d''identité légalement effectué par les forces de l''ordre, toute personne devra permettre son identification et retirer temporairement tout dispositif dissimulant son visage lorsque cela est nécessaire à la vérification de son identité.
La dissimulation du visage pourra également être interdite à l''intérieur ainsi qu''aux abords immédiats de certains lieux sensibles, notamment les institutions judiciaires, bâtiments gouvernementaux, postes des forces de l''ordre, infrastructures hospitalières, infrastructures sécurisées ou toute zone faisant l''objet d''un dispositif particulier de sécurité publique.
En cas d''état d''urgence, de menace grave ou d''opération exceptionnelle de sécurité, les autorités compétentes pourront temporairement restreindre ou interdire la dissimulation du visage dans certaines zones déterminées.
Toute application du présent article devra respecter les principes de nécessité, de proportionnalité ainsi que les droits et libertés garantis par les Constitutions des États-Unis et de l''État de San Andreas.', null, 104),
  ('A7103', '7103', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Le fait de quitter les lieux après avoir causé un dommage ou un danger sans se soumettre aux obligations légales est reconnu comme délit de fuite et constitue une infraction pénale.', null, 105),
  ('A7104', '7104', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Toute non présentation à une convocation officielle publiée par un service public (SAHP, LSPD ou BCSD) ou par une institution publique (Gouvernement, Mairie, Bureau du Procureur, Sénat, Cour ou Cour Suprême) constitue une infraction pénale.', null, 106),
  ('A7105', '7105', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Le fait de violer délibérément les obligations imposées par une décision judiciaire est reconnu comme non-respect de contrôle judiciaire et constitue une infraction pénale.', null, 107),
  ('A7106', '7106', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 1 - Infractions aux décisions et ordres publics', 'Le fait, pour une personne légalement détenue, placée sous garde, sous arrestation ou sous contrôle judiciaire, de se soustraire volontairement à la mesure de privation ou de restriction de liberté qui lui est légalement imposée est reconnu comme évasion et constitue une infraction pénale.', null, 108),
  ('A7201', '7201', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 2 - Atteintes à la justice et à la vérité', 'Toute entrave volontaire à une enquête, une poursuite ou une décision judiciaire est reconnue comme obstruction à la justice et constitue une infraction pénale.', null, 109),
  ('A7202', '7202', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 2 - Atteintes à la justice et à la vérité', 'Le fait de falsifier un document ou d''utiliser sciemment un document falsifié afin d''en tirer un avantage ou de produire un effet juridique est reconnu comme faux ou usage de faux et constitue une infraction pénale.', null, 110),
  ('A7203', '7203', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 2 - Atteintes à la justice et à la vérité', 'Le fait de faire sciemment une déclaration mensongère sous serment devant une autorité compétente est reconnu comme parjure et constitue une infraction pénale.', null, 111),
  ('A7204', '7204', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 2 - Atteintes à la justice et à la vérité', 'Le fait, pour deux (2) personnes ou plus, de s''entendre en vue de commettre une attaque violente ou armée contre :
- une Mairie située dans l''État de San Andreas, ou l''un de ses bâtiments officiels.
- le Gouvernement de l''État de San Andreas, ou l''un de ses bâtiments officiels.
La conspiration n''est caractérisée que si cette entente est établie de manière claire et qu''elle s''accompagne d''éléments objectifs démontrant une volonté concrète de passage à l''action. En ce sens est reconnu comme conspiration et constitue une infraction pénale.
La seule expression d''une opinion, d''une colère ou de propos non suivis d''organisation concrète ne peut suffire à constituer l''infraction', null, 112),
  ('A7301', '7301', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 3 - Atteintes à l''autorité et aux institutions', 'Le fait de se faire passer pour une autre personne ou pour un agent public afin d''en tirer un avantage est reconnu comme usurpation d''identité ou de fonction et constitue une infraction pénale.', null, 113),
  ('A7302', '7302', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 3 - Atteintes à l''autorité et aux institutions', 'Le fait d''empêcher ou de perturber volontairement l''action légale des services publics est reconnu comme entrave à intervention des services publics et constitue une infraction pénale.', null, 114),
  ('A7303', '7303', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 3 - Atteintes à l''autorité et aux institutions', 'Le fait de proposer ou d''accepter un avantage indu dans l''exercice d''une fonction publique est reconnu comme corruption et constitue une infraction pénale.', null, 115),
  ('A7304', '7304', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 3 - Atteintes à l''autorité et aux institutions', 'Toute manœuvre frauduleuse, ou non-respect des dispositions prises par le Code électoral, visant à altérer la sincérité d''un scrutin est reconnu comme fraude électorale et constitue une infraction pénale.', null, 116),
  ('A7305', '7305', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 3 - Atteintes à l''autorité et aux institutions', 'Tout acte criminel grave commis dans le but d''intimider la population, de perturber gravement l''ordre public ou de contraindre une autorité publique par la violence ou la menace est reconnu comme acte de terrorisme et constitue une infraction pénale.', null, 117),
  ('A7306', '7306', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 3 - Atteintes à l''autorité et aux institutions', 'I. – Constituent un outrage à magistrat les gestes, écrits, menaces ou insultes adressés à un magistrat dans l''exercice de ses fonctions.
II. – Sont considérés comme magistrats au sens du présent article :
– Le Juge Président de la Cour Suprême de l''État de San Andreas ;
– Les Juges Associés de la Cour Suprême de l''État de San Andreas ;
– Le Procureur de Comté ;
– Les Procureurs Adjoints.
III. – L''outrage à magistrat est puni d''une amende de 10.000 dollars et de quinze (15) minutes d''emprisonnement.', null, 118),
  ('A7401', '7401', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 4 - Ordre public et sécurité collective', 'Le fait de solliciter de manière insistante, agressive ou coercitive des dons sur la voie publique, en violation des règles d''ordre public est reconnu comme mendicité et constitue une infraction pénale', null, 119),
  ('A7402', '7402', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 4 - Ordre public et sécurité collective', 'Le fait de se trouver en état d''ivresse manifeste sur la voie publique lorsqu''un tel état crée un danger pour soi-même ou pour autrui est reconnu comme ivresse sur la voie publique et constitue une infraction pénale.', null, 120),
  ('A7403', '7403', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 4 - Ordre public et sécurité collective', 'Le fait de solliciter volontairement et sans motif légitime les services d''urgence, en causant une mobilisation injustifiée de moyens publics, est reconnu comme appel abusif aux services d''urgence et constitue une infraction pénale.', null, 121),
  ('A7404', '7404', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 4 - Ordre public et sécurité collective', 'Le fait de porter atteinte de manière volontaire à la quiétude ou à la tranquillité d''un lieu public est reconnu comme trouble à l''ordre public et constitue une infraction pénale.', null, 122),
  ('A7405', '7405', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 4 - Ordre public et sécurité collective', 'Le fait d''organiser ou de participer à un rassemblement public en violation d''une interdiction légalement motivée tenant à la sécurité ou à l''ordre public est reconnu comme organisation ou participation à une manifestation illégale et constitue une infraction pénale.', null, 123),
  ('A7501', '7501', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'Le devoir de réserve impose à tout employé d''un service public ou privé d''adopter une attitude de neutralité et de discrétion dans l''exercice de ses fonctions. Il vise à garantir l''impartialité, la confidentialité et la protection des informations dont l''agent a connaissance dans le cadre de son activité professionnelle.', null, 124),
  ('A7501.1', '7501.1', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'Tout employé tenu par le devoir de réserve est dans l''obligation de ne divulguer aucune information obtenue dans l''exercice de ses fonctions, que ce soit à des tiers, au public ou même à ses collègues, sauf si cette divulgation est strictement encadrée par la loi ou expressément autorisée par une autorité compétente.

Cette interdiction couvre notamment :

- toute déclaration publique pouvant compromettre l''image, l''intégrité ou la neutralité de l''institution ou de l''entreprise ;
- toute divulgation d''informations sensibles sur un dossier en cours, y compris à des proches ou sur des réseaux sociaux ;
- toute diffusion de documents internes, de notes confidentielles ou d''échanges professionnels protégés.', null, 125),
  ('A7501.2', '7501.2', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'Le non-respect du devoir de réserve peut notamment être caractérisé par :

- la diffusion volontaire ou involontaire d''informations confidentielles ;
- l''enregistrement et la publication de conversations internes sans autorisation ;
- la communication d''informations stratégiques ou institutionnelles à des personnes non autorisées ;
- le partage de documents internes à des tiers sans justification légale.

Toute divulgation non autorisée de ces informations est reconnue comme violation du devoir de réserve et constitue une infraction pénale.', null, 126),
  ('A7501.3', '7501.3', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'La violation du devoir de réserve est punie d''une amende de quinze mille (15 000) dollars et d''une peine de détention de trente (30) minutes.', null, 127),
  ('A7502', '7502', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'Toute personne tenue au secret professionnel, de par sa profession ou ses fonctions, qui divulgue des informations confidentielles obtenues dans l''exercice de ses responsabilités, sans autorisation légale ou consentement éclairé de la personne concernée, commet une violation du secret professionnel et constitue une infraction pénale.', null, 128),
  ('A7502.1', '7502.1', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'Cette infraction est constituée dès lors que l''auteur communique, transmet ou exploite des informations protégées, que ce soit verbalement, par écrit, sous forme numérique ou par tout autre moyen, y compris indirectement.
La simple tentative de divulgation ou la négligence entraînant une fuite d''informations confidentielles peut également être réprimée au titre de cette infraction.', null, 129),
  ('A7502.2', '7502.2', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'Sont notamment concernés, sans que cette liste soit exhaustive :
- les professionnels de santé ;
- les avocats et auxiliaires de justice ;
- les forces de l''ordre et magistrats ;
les fonctionnaires et agents publics soumis à une obligation de discrétion.', null, 130),
  ('A7502.3', '7502.3', 'Partie II', 'Titre VII – Infractions contre l''autorité publique', 'Chapitre 5 - Manquements aux obligations professionnelles', 'La violation du secret professionnel est punie d''une amende de trente mille (30 000) dollars et d''une peine de détention de trente (30) minutes.', null, 131),
  ('A8101', '8101', 'Partie II', 'Titre VIII – Produits stupéfiants', 'Chapitre unique', 'Sont considérées comme produits stupéfiants les substances classées comme telles par la loi ou par règlement pris conformément à celle-ci.', null, 132),
  ('A8102', '8102', 'Partie II', 'Titre VIII – Produits stupéfiants', 'Chapitre unique', 'Sont considérés comme produits stupéfiants illégaux toute substance ou préparation ayant des effets psychotropes ou altérant les facultés physiques ou mentales, et dont la production, la fabrication, la possession, le transport, la distribution, la vente ou la consommation ne sont pas autorisés par les autorités compétentes.', null, 133),
  ('A8103', '8103', 'Partie II', 'Titre VIII – Produits stupéfiants', 'Chapitre unique', 'La possession de produit stupéfiant en quantité supérieure à six (6) unité est non autorisées et constitue une infraction pénale. La possession de produit stupéfiant en quantité inférieure à six (6) unités, n''est pas autorisée et entraine une saisie des substances sans poursuite pénale.', null, 134),
  ('A8104', '8104', 'Partie II', 'Titre VIII – Produits stupéfiants', 'Chapitre unique', 'La vente d''un produit stupéfiant en échange d''un bien matériel ou immatériel constitue une infraction pénale.', null, 135),
  ('A8105', '8105', 'Partie II', 'Titre VIII – Produits stupéfiants', 'Chapitre unique', 'La production, transformation, transport ou importation de stupéfiants dans un cadre organisé constitue un trafic à partir de 50 pochons et est sanctionnée pénalement.', null, 136),
  ('A8106', '8106', 'Partie II', 'Titre VIII – Produits stupéfiants', 'Chapitre unique', 'La consommation de produit stupéfiant dans l''espace public ou le fait de se trouver dans l''espace public en étant sous influence de produit stupéfiant est reconnu comme consommation de produits stupéfiant et constitue une infraction pénale.', null, 137),
  ('A9101', '9101', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'La détention d''argent liquide à domicile pour un montant supérieur à un million de dollars est reconnue comme possession d''argent non-déclaré et constitue une infraction pénale.', null, 138),
  ('A9102', '9102', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'La détention d''argent liquide en quantité supérieure à 6000$ est reconnue comme possession d''argent en quantité non autorisée et constitue une infraction pénale.', null, 139),
  ('A9103', '9103', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'Le fait d''obtenir un bien, un service ou un avantage par tromperie, dissimulation ou manœuvres frauduleuses est reconnu comme fraude et constitue une infraction pénale.', null, 140),
  ('A9104', '9104', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'Le fait de se soustraire frauduleusement à l''impôt ou aux contributions obligatoires est reconnu comme évasion fiscale et constitue une infraction pénale.', null, 141),
  ('A9105', '9105', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'Le fait de dissimuler, convertir ou réintroduire des fonds issus d''une activité criminelle est reconnu comme blanchiment de capitaux et constitue une infraction pénale.', null, 142),
  ('A9106', '9106', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'Constitue une fraude fiscale toute action ou omission ayant pour objet ou pour effet de soustraire, en tout ou partie, un contribuable au paiement de l''imposition.', 'Applicable uniquement sur Los Santos.', 143),
  ('A9107', '9107', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 1 - Infractions de dissimulation et fraude', 'Sont notamment considérés comme des actes de fraude fiscale, la liste non exhaustive suivante : dissimulation totale ou partielle des revenus, bénéfices et/ou chiffres d''affaires d''une entreprise ; la falsification de documents comptables et/ou fiscaux ; l''usage de montages destinés à masquer la réalité d''une activité économique ; toute déclaration mensongère ou manœuvre visant à échapper à l''imposition.', 'Applicable uniquement sur Los Santos.', 144),
  ('A9201', '9201', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 2 - Infraction de gestion et de confiance', 'Le fait de détourner un bien, un pouvoir ou une mission confiés à titre temporaire ou spécifique est reconnu comme abus de confiance et constitue une infraction pénale.', null, 145),
  ('A9202', '9202', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 2 - Infraction de gestion et de confiance', 'L''usage abusif des biens, du crédit ou de la falsification d''une entité à des fins personnelles est reconnu comme abus de biens sociaux et constitue une infraction pénale.', null, 146),
  ('A9203', '9203', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 2 - Infraction de gestion et de confiance', 'Le fait, pour une personne dépositaire de fonds publics ou privés, de les utiliser ou détourner à des fins étrangères à leur destination légitime est reconnu comme détournement de fonds et constitue une infraction pénale', null, 147),
  ('A9301', '9301', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 2 - Infraction de gestion et de confiance', 'Le fait de ne pas payer ses amendes après le délai de 72h00 est constitutif du délit de non respect d''un délai de paiement. Le non respect de ce délai pourra entraîner la majoration des amendes initiales de 100% ou une saisie sur les biens meubles ou immobiliers de l''individu.', null, 148),
  ('A9302', '9302', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 2 - Infraction de gestion et de confiance', 'En matière d''amende pénale, elle peut être prononcée, en toute matière, par un juge. En matière délictuelle, elle peut être prononcée par le Bureau du Procureur qui peut déléguer ses fonctions aux services de police. En matière criminelle, elle peut être prononcée par le juge qui peut déléguer ses fonctions au bureau du Procureur. Celui-ci ne peut déléguer ces fonctions qu''aux services de police.', null, 149),
  ('A9303', '9303', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 3 - Des peines prononcées', 'En cas d''amende impayée, le juge peut décider de majorer la peine ou peut déléguer cette tâche au Bureau du Procureur. Si les peines sont trop importantes, le juge ou le Bureau du procureur peuvent notamment procéder à une saisie des biens mobiliers et immobiliers du prévenu ou de l''accusé à défaut de paiement.', null, 150),
  ('A9303.1', '9303.1', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 3 - Des peines prononcées', 'En cas de facture impayée les peines sont similaires à celles des amendes impayées avec un délai de paiement de celle-ci de 72h avec une majoration de 20% si le susmentionné délai est dépassé.', null, 151),
  ('A9304', '9304', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 3 - Des peines prononcées', 'La peine de travail d''intérêt général peut être prononcée par le Juge ou le Bureau du Procureur.', null, 152),
  ('A9304.1', '9304.1', 'Partie II', 'Titre IX – Infractions financières', 'Chapitre 3 - Des peines prononcées', 'En cas de manquement ou de conduite inappropriée durant la détention, la SAHP est habilitée à réévaluer la peine en cours et à en prolonger la durée, proportionnellement à la gravité des faits constatés.', null, 153),
  ('A10101', '10101', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 1 - Infractions routières', 'Le fait de conduire un véhicule motorisé sans être titulaire d''un permis de conduire valide correspondant à la catégorie du véhicule est reconnu comme conduite sans permis et constitue une infraction pénale.', null, 154),
  ('A10101.1', '10101.1', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 1 - Infractions routières', 'Le fait de conduire un véhicule terrestre à moteur sans être titulaire du permis requis constitue un délit.
Toutefois, par dérogation, la conduite d''un véhicule de type Faggio ou Caddie est autorisée à partir de seize (16) ans sans permis, conformément aux dispositions du Code de la Route.', null, 155),
  ('A10102', '10102', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 1 - Infractions routières', 'Le fait de conduire un véhicule d''une manière manifestement dangereuse, caractérisée par une violation délibérée ou une imprudence grave des règles de sécurité, exposant autrui à un risque immédiat de mort ou de blessure grave, est reconnu comme conduite dangereuse et constitue une infraction pénale.', null, 156),
  ('A10103', '10103', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 1 - Infractions routières', 'Le fait de conduire un véhicule sous l''emprise d''alcool ou de produit stupéfiant affectant les capacités physiques ou mentales, dans des conditions dépassant les seuils administratifs définis par le Code de la route, est reconnu comme conduite sous emprise et constitue une infraction pénale.', null, 157),
  ('A10104', '10104', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 1 - Infractions routières', 'Le fait de participer, en qualité de conducteur ou d''organisateur, à une course de véhicules non autorisée sur la voie publique est reconnu comme course illégale et constitue une infraction pénale.', null, 158),
  ('A10105', '10105', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 1 - Infractions routières', 'Le fait de circuler avec un véhicule muni de plaques d''immatriculation falsifiées, usurpées ou dissimulées est reconnu comme circulation avec un véhicule faussement immatriculé et constitue une infraction pénale.', null, 159),
  ('A10201', '10201', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 2 - Infractions maritimes', 'Le fait de naviguer sans permis avec une embarcation de catégorie 2 est reconnu comme navigation sans permis et constitue une infraction pénale.', null, 160),
  ('A10202', '10202', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 2 - Infractions maritimes', 'Le fait de naviguer d''une manière manifestement dangereuse, caractérisée par une violation délibérée ou une imprudence grave des règles de sécurité, exposant autrui à un risque immédiat de mort ou de blessure grave, est reconnu comme navigation dangereuse et constitue une infraction pénale.', null, 161),
  ('A10203', '10203', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 2 - Infractions maritimes', 'Le fait de naviguer dans des zones interdites à la navigation, définies par la loi, est reconnu comme navigation en zone interdite et constitue une infraction pénale.', null, 162),
  ('A10301', '10301', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 3 - Infractions aériennes', 'Le fait de piloter un aéronef sans licence est reconnu comme pilotage d''un aéronef sans licence et constitue une infraction pénale.', null, 163),
  ('A10302', '10302', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 3 - Infractions aériennes', 'Le fait de piloter un aéronef d''une manière manifestement dangereuse, caractérisée par une violation délibérée ou une imprudence grave des règles de sécurité, exposant autrui à un risque immédiat de mort ou de blessure grave, est reconnu comme pilotage dangereux d''un aéronef et constitue une infraction pénale.', null, 164),
  ('A10303', '10303', 'Partie II', 'Titre X – Infractions pénales routières, maritimes et aériennes', 'Chapitre 3 - Infractions aériennes', 'Le fait de survoler des zones définies par la loi comme interdites en aéronef est reconnu comme survol en aéronef de zone interdite et constitue une infraction pénale.', null, 165),
  ('A11101', '11101', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Le fait d''organiser un évènement dans un espace protégé, sans que celui-ci soit décrété et approuvé par la Mairie du comté dans lequel se situe l''espace protégé, est reconnu comme organisation de manifestation illégale dans un espace protégé et constitue une infraction pénale.', null, 166),
  ('A11102', '11102', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Le fait de construire dans un espace protégé, sans autorisation de la Mairie du comté dans lequel se trouve l''espace protégé, est reconnu comme construction illégale dans un espace protégé et constitue une infraction pénale.', null, 167),
  ('A11103', '11103', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Le fait de ne pas respecter les quotas de pêche ou de chasse fixés par les autorités est reconnu comme destruction de la faune et constitue une infraction pénale.', null, 168),
  ('A11103.1', '11103.1', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Constitue une destruction de la faune le fait de capturer, tuer, prélever, détenir, transporter ou commercialiser des animaux sauvages, terrestres ou aquatiques en dépassant les quotas autorisés par la réglementation environnementale en vigueur. L''infraction est constituée dès le premier individu excédentaire.', 'Applicable uniquement à Blaine County.', 169),
  ('A11103.2', '11103.2', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Le dépassement est qualifié de grave lorsque le volume total d''unités saisies est compris entre 101 et 199 unités, exprimées en nombre, poids ou équivalent. Ces dispositions s''appliquent aux personnes physiques ainsi qu''aux personnes morales dont l''activité principale n''est ni la pêche ni la chasse professionnelle.', 'Applicable uniquement à Blaine County.', 170),
  ('A11103.3', '11103.3', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'En cas de dépassement, la part excédant le quota peut être saisie ; l''intégralité des prises peut être saisie en cas de dépassement significatif, répété ou supérieur à 100 unités. À défaut de circonstance aggravante, la saisie peut être limitée à la part excédentaire.', 'Applicable uniquement à Blaine County.', 171),
  ('A11103.4', '11103.4', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'L''amende est fixée sur une base initiale de 300 $ par unité excédentaire et peut être étendue à la totalité des prises lorsque le dépassement excède 100 unités ou présente un caractère aggravant. Les peines peuvent être aggravées en cas de récidive, de dissimulation ou falsification des quantités ou d''organisation concertée à but lucratif.', 'Applicable uniquement à Blaine County.', 172),
  ('A11104', '11104', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Le fait de chasser ou pêcher une espèce protégée est reconnu comme pêche ou chasse illégale d''une espèce protégée et constitue une infraction pénale.', null, 173),
  ('A11105', '11105', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'La vente d''une espèce protégée en échange d''un bien matériel ou immatériel est reconnue comme vente illégale d''espèce protégée et constitue une infraction pénale.', null, 174),
  ('A11106', '11106', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Le fait de transformer, transporter, importer ou vendre des espèces protégées dans un cadre organisé est reconnu comme trafic d''espèce protégée et constitue une infraction pénale.', null, 175),
  ('A11107', '11107', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Toute action causant un dommage écologique grave, en participant au dépassement manifeste et non négligeable des limites planétaires, commise en connaissance des conséquences qui allaient en résulter et qui ne pouvaient être ignorées, et reconnu comme écocide et constitue une infraction pénale.', null, 176),
  ('A11107.1', '11107.1', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Constitue un écocide toute action intentionnelle ou résultant d''une négligence grave ayant causé une atteinte grave, durable et significative à l''environnement sur le territoire de Blaine County.', 'Applicable uniquement à Blaine County.', 177),
  ('A11107.2', '11107.2', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'L''écocide est notamment caractérisé lorsque les faits entraînent la destruction, l''exploitation, la pollution ou la saisie d''un volume égal ou supérieur à 200 unités de ressources naturelles ; ce seuil qualifie une atteinte écologique majeure constituant un crime grave.', 'Applicable uniquement à Blaine County.', 178),
  ('A11107.3', '11107.3', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Ces dispositions s''appliquent aux personnes physiques ainsi qu''aux personnes morales dont l''activité principale n''est ni de la pêche ni de la chasse professionnelle ; pour les personnes morales exerçant une activité professionnelle de pêche ou de chasse, le seuil est fixé à 400 unités.', 'Applicable uniquement à Blaine County.', 179),
  ('A11107.4', '11107.4', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'L''écocide est passible d''une amende pouvant atteindre 175 000 $ et d''une peine de 90 minutes d''emprisonnement. Le tribunal peut ordonner la confiscation des permis, licences ou autorisations liés aux activités en cause, l''interdiction d''exercer une activité ayant conduit aux faits, la saisie des équipements utilisés ainsi que toute mesure de réparation ou de compensation écologique.', 'Applicable uniquement à Blaine County.', 180),
  ('A11108', '11108', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Il est institué un chef d''accusation autonome intitulé Destruction de la flore. Constitue le délit le fait de porter atteinte, volontairement ou par négligence grave, à des végétaux ou formations végétales, cultures naturelles ou protégées, à des forêts ou zones boisées ou à des espèces végétales rares ou protégées.', 'Applicable uniquement à Blaine County.', 181),
  ('A11108.1', '11108.1', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'La destruction de la flore est notamment caractérisée par l''arrachage, l''abattage ou la coupe non autorisée de végétaux, l''incendie volontaire ou résultant d''un défaut de maîtrise, ainsi que l''utilisation de substances chimiques, biologiques ou de moyens mécaniques entraînant une dégradation durable ou irréversible de la végétation.', 'Applicable uniquement à Blaine County.', 182),
  ('A11108.2', '11108.2', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'Les peines sont déterminées en fonction de l''étendue et de la gravité des dommages, du caractère protégé des espèces ou milieux concernés et du degré d''intention ou de négligence de l''auteur. Le délit est autonome et peut être poursuivi indépendamment ou cumulativement avec toute autre infraction environnementale.', 'Applicable uniquement à Blaine County.', 183),
  ('A11108.3', '11108.3', 'Partie II', 'Titre XI – Infractions pénales au Code de l''environnement', 'Chapitre unique', 'La destruction de la flore est passible d''une amende nominale de 5 000 $ et d''une détention nominale de 15 minutes.', 'Applicable uniquement à Blaine County.', 184);
